ee:message.ee:set-payload:
%dw 2.0
output application/json

// Variables de control
var statusCode = vars.vRespuesta.status default 200
var responseBody = vars.vRespuesta

// Booleano para saber si el cliente realmente vino en el body
var hasCustomer = responseBody.GetPartnerViewResponse != null
---
{
  "code": statusCode as String,

  "message": if (hasCustomer) "Subscriber retrieved successfully" 
             else responseBody.error,

  "data": if (hasCustomer) do {
      // Usamos 'do' para crear variables locales solo si hay éxito
      var customer = responseBody.GetPartnerViewResponse.GetPartnerViewResult.Customer
      var individual = customer.IndividualRole
      ---
      {
        "id": customer.ID,
        "serviceSpecification": {
          "name": "OTT"
        },
        "state": {
          "id": customer.status.id,
          "name": customer.status.name
        },
        "customer": [
          {
            "id": customer.ID,
            "name": individual.NameUsing.IndividualNames.formattedName,
            "givenNames": individual.NameUsing.IndividualNames.givenNames,
            "familyNames": individual.NameUsing.IndividualNames.familyNames,
            "middleNames": individual.NameUsing.IndividualNames.middleNames default "",
            "aristocraticTitle": individual.NameUsing.IndividualNames.aristocraticTitle default "",
            "aliveDuring": {
              "startDateTime": individual.aliveDuring.startDateTime
            },
            "identifiedBy": individual.IdentifiedBy.IndividualIdentifications filter ($.cardNr != null) map (id) -> {
              "scan": id.scan,
              "cardNr": id.cardNr
            },
            "contactMedium": customer.ContactableVia.ContactMedium map (contact) -> {
              "eMailAddress": contact.eMailAddress default "",
              "addressId": contact.AddressId,
              "eMailProtocol": contact.eMailProtocol default "Email"
            },
            "address": customer.AddressList.UrbanPropertyAddress map (addr) -> {
              "addressCode": addr.addressCode default "",
              "city": addr.city,
              "streetNrFirst": addr.streetNrFirst,
              "locality": addr.locality,
              "streetName": addr.streetName,
              "postCode": addr.postCode
            }
          }
        ],
        "serviceCharacteristic": [
          {
            "name": "customerInquiryList",
            "value": responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerInquiryList.CustomerInquiry default []
          },
          {
            "name": "customerProductList",
            // AQUÍ ESTABA EL ERROR: Filtramos para que solo pasen Objetos
            "value": (responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerProductList.Product default []) 
                     filter ($ is Object) map (prod) -> {
              "productStatus": prod.productStatus,
              "productCategory": prod.productCategory
            }
          }
        ]
      }
  } else {} // Si no existe el cliente, data queda como objeto vacío
}

%dw 2.0
output application/json

var source = payload
var prod = source.product
---
{
  "CaptureCustomerProductRequest": {
    "CaptureCustomerProduct": {
      "DeleteOffer": "false",
      "ActivateInAllDevices": "true",
      "ProductsCollection": [
        {
          "CustomerProductOffer": {
            "Product": {
              // Convertimos a String para asegurar que coincida con el destino
              "productKey": prod.productKey as String default "",
              "ID": prod.id as String default "",
              "productCategory": {
                "type": {
                  "code": prod.productCategory."type".code
                }
              }
            }
          }
        }
      ]
    }
  }
}

%dw 2.0
output application/json

// Acceso rápido a la oferta y al producto
var offer = payload.ProductsCollection.CustomerProductOffer
var prod = offer.Product
---
{
  "code": "200",
  "message": "Product activated successfully",
  "result": {
    "action": "activation",
    "customer": {
      "customerKey": offer.CustomerKey
    },
    "product": {
      // Convertimos a número para mantener consistencia con el origen inicial
      "id": prod.ID as Number,
      "productKey": prod.productKey as Number,
      "productCategory": {
        "type": {
          "code": prod.productCategory."type".code
        }
      }
    }
  }
}

%dw 2.0
output application/json


var activate = payload.ActivateRefreshResponse
var meta = activate.ResponseMetadata
---
{
  "code": "200",
  "message": "Reprovision processed successfully",
   "data": {
	    "responseMetadata": {
	      "timeStamp": meta.timeStamp,
	      "requestID": meta.requestID
	    }
   }
}

%dw 2.0
output application/json

// Simplificamos la ruta al objeto principal para que el script sea más limpio
var schedule = payload.CancelCustomerProductsResponse.CancelCustomerProductsResult.CustomerScheduleCollection.CustomerSchedules
var metadata = payload.CancelCustomerProductsResponse.responseMetadata.requestMetadata
---
{
  "code": "200",
  "message": "Cancel processed successfully",
  "result": {
    "action": "cancelCustomer",
    "customer": {
      "customerKey": schedule.CustomerKey
    },
    "product": {
      // Nota: Si necesitas que sea estático "directv", cambia schedule.Product.name por "directv"
      "name": schedule.Product.name, 
      "id": schedule.Product.id as Number default "0"
    },
    "order": {
      "parentId": schedule.ParentId,
      "status": {
        "name": schedule.Status.name,
        "id": schedule.Status.id
      },
      "entity": {
        "type": schedule.Entity.Type,
        "id": schedule.Entity.ID
      },
      "description":  schedule.Description,
      "user": {
        "name": schedule.User.name,
        "id": schedule.User.id
      },
      "event": {
        "name": schedule.Event.name,
        "id": schedule.Event.id
      },
      "createDatetime": schedule.CreateDatetime,
      "id": schedule.ID,
      "reason": {
        "name": schedule.Reason.name,
        "id": schedule.Reason.id
      },
      "executeDatetime": schedule.ExecuteDatetime
    }
  },
  "responseMetadata": {
    "requestMetadata": {
      "systemId": metadata.systemID,
      "sender": {
        "country": metadata.sender.country
      },
      "requestId": metadata.requestID,
      "userId": metadata.userID
    }
  }
}

%dw 2.0
output application/json

// Guardamos la ruta de la metadata en una variable para no repetir código largo
var responseMeta = payload.ReconnectCustomerProductResponse.responseMetadata
var requestMeta = responseMeta.requestMetadata
---
{
  "code": "200",
  "message": "Reconnect processed successfully",
  "result": {
    "action": "reconnectCustomer"
  },
  "responseMetadata": {
    "requestMetadata": {
      "systemId": requestMeta.systemID,
      "sender": {
        "country": requestMeta.sender.country
      },
      "requestId": requestMeta.requestID,
      "userId": requestMeta.userID
    },
    "returnCode": responseMeta.returnCode,
    "returnMessage": responseMeta.returnMessage
  }
}

%dw 2.0
output application/json

// Variables para simplificar el acceso a las estructuras
var schedule = payload.CancelCustomerProductsResponse.CancelCustomerProductsResult.CustomerScheduleCollection.CustomerSchedules
var metadata = payload.CancelCustomerProductsResponse.responseMetadata.requestMetadata
---
{
  "code": "200",
  "message": "Cancel processed successfully",
  "result": {
    "action": "cancelAmazon",
    "customer": {
      "customerKey": schedule.CustomerKey
    },
    "product": {
      "name": schedule.Product.name,
      "id": schedule.Product.id as Number default vars.productId
    },
    "order": {
      // Como no viene ParentId en el origen, usamos "0" por defecto
      "parentId": schedule.ParentId default "0",
      "status": {
        "name": schedule.Status.name,
        "id": schedule.Status.id
      },
      "entity": {
        "type": schedule.Entity.Type,
        "id": schedule.Entity.ID
      },
      "description": schedule.Description,
      "user": {
        "name": schedule.User.name,
        "id": schedule.User.id
      },
      "event": {
        "name": schedule.Event.name,
        "id": schedule.Event.id
      },
      "createDatetime": schedule.CreateDatetime,
      "id": schedule.ID,
      "reason": {
        "name": schedule.Reason.name,
        "id": schedule.Reason.id
      },
      "executeDatetime": schedule.ExecuteDatetime
    }
  },
  "responseMetadata": {
    "requestMetadata": {
      "systemId": metadata.systemID,
      "sender": {
        "country": metadata.sender.country
      },
      "requestId": metadata.requestID,
      "userId": metadata.userID
    }
  }
}

%dw 2.0
output application/json
---
{
  "actionType": "ReconnectCustomerProductsAmazon",
  "DeleteOffer": payload.flags.deleteOffer as String,
  "ActivateInAllDevices": payload.flags.activateInAllDevices as String, 
  "ProductsCollection": [
    {
      "CustomerProductOffer": {
        "Product": {
          "productKey": payload.product.productKey as String,
          "ID": payload.product.id as String,
          "productCategory": {
            "type": {
              "code": payload.product.productCategory."type".code
            }
          }
        }
      }
    }
  ]
}

%dw 2.0
output application/json

// Variables para apuntar limpiamente al nuevo origen
var metadata = payload.ProductsCollection.responseMetadata.requestMetadata
---
{
  "code": "200",
  "message": "Reconnect processed successfully",
  "result": {
    "action": "reconnectAmazon"
  },
  "responseMetadata": {
    "requestMetadata": {
      "systemId": metadata.systemID,
      "sender": {
        "country": metadata.sender.country
      },
      "requestId": metadata.requestID as Number default 0, // Convierte "1234" a número
      "userId": metadata.userID
    },
    "returnCode": 0,
    "returnMessage": "SUCCESS"
  }
}
